/bin/bash -lc "cd /workspace && python3 - <<'EOF'
import ast, pathlib
rows=[]
for p in sorted(pathlib.Path('tests').rglob('*.py')):
    src=p.read_text()
    try:
        tree=ast.parse(src)
    except SyntaxError:
        continue
    tot=miss=0
    for node in ast.walk(tree):
        if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef)):
            tot+=1
            args=[a for a in list(node.args.posonlyargs)+list(node.args.args)+list(node.args.kwonlyargs) if a.arg not in ('self','cls')]
            missing_args=[a for a in args if a.annotation is None]
            if node.returns is None or missing_args:
                miss+=1
    if tot:
        rows.append((miss/tot, miss, tot, str(p)))
rows.sort(reverse=True)
for r in rows:
    if r[0]>0.5:
        print(f\"{r[3]:55s} {r[1]:3d}/{r[2]:3d} untyped-ish\")
EOF"

